@dataclass
class Depends:
    dependency: Optional[Callable[..., Any]] = None
    use_cache: bool = True
    scope: Union[Literal["function", "request"], None] = None

    def __hash__(self):
        # Workaround to ensure hashability even if dependency is not hashable
        dep_id = id(self.dependency) if self.dependency is not None else None
        return hash((dep_id, self.use_cache, self.scope))

    def __eq__(self, other):
        if not isinstance(other, Depends):
            return NotImplemented
        # Equality check based on type and identity of dependency
        if self.dependency is None and other.dependency is None:
            return True
        if self.dependency is None or other.dependency is None:
            return False
        return type(self.dependency) is type(other.dependency) and self.dependency is other.dependency

